package com.aaliyun.leadnews.behavior.service;
import com.aaliyun.leadnews.behavior.mapper.BehaviorMapper;import org.slf4j.*;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Service;
@Service public class BehaviorReconciliationService {private static final Logger log=LoggerFactory.getLogger(BehaviorReconciliationService.class);private final BehaviorMapper db;private final BehaviorApplicationService behavior;public BehaviorReconciliationService(BehaviorMapper db,BehaviorApplicationService behavior){this.db=db;this.behavior=behavior;}@Scheduled(fixedDelayString="${leadnews.behavior.reconcile-millis:300000}")public void initializeMissingCounters(){db.recentStats(500).forEach(row->{try{behavior.ensureCounter(((Number)row.get("articleId")).longValue());}catch(RuntimeException e){log.warn("Behavior reconciliation deferred articleId={}",row.get("articleId"));}});}}
